/* AP Psychology Course and Exam Description (2024-25 onward), Unit 1, topics 1.1–1.6; drug effects on neural firing are taught inside 1.3.
   https://apcentral.collegeboard.org/courses/ap-psychology/course
   Original wording; every study, dataset and patient described as fictional is invented for practice. Typical textbook values
   (such as a resting potential near -70 mV) vary by neuron and by source and are hedged where they appear.
   Illustration requests are listed in ART_REQUESTS.md; labels and data are drawn in code. */
const fig=(title,o)=>({t:'figure',title,dots:'',...o,hide:Object.keys(o.pts||{}).join('')});
const board=(title,lines,why)=>({t:'board',title,lines,...(why?{why}:{}),box:true});
const bars=(title,labels,values)=>({t:'chart',kind:'bars',title,bars:labels.map((label,i)=>({label,value:values[i]}))});
const choose=(right,wrong,k)=>{const o=[...wrong];o.splice(k%3,0,right);return {text:o.map((x,i)=>`${'ABC'[i]}: ${x}`).join(', '),letter:'ABC'[o.indexOf(right)]};};
const scenario=(title,p)=>{const lines=[];let line='';for(const word of p.split(' ')){if((line+' '+word).length>49){lines.push(line);line=word;}else line+=(line?' ':'')+word;}if(line)lines.push(line);return {t:'board',title,lines};};
const rnd=n=>Math.round(n*1e4)/1e4;
/* dia: boxes placed in pixel units (x right, y up, the picture is 552 wide); links are arrows from one box edge to another; extra holds raw pts, segs and notes */
const dia=(title,nodes,links,extra={},h=192)=>{const pts={},polys=[],segs=[],notes=[];
 nodes.forEach((n,i)=>{Object.assign(pts,{['A'+i]:[n.x,n.y],['B'+i]:[n.x+n.w,n.y],['C'+i]:[n.x+n.w,n.y+n.h],['D'+i]:[n.x,n.y+n.h]});polys.push({v:`A${i}B${i}C${i}D${i}`,col:n.col??i%4});
  const L=n.text.split('|'),cx=n.x+n.w/2,cy=n.y+n.h/2;L.forEach((t,k)=>notes.push({at:[cx,cy+(L.length-1)*7.5-k*15],text:t}));});
 const edge=(n,dx,dy)=>{const t=Math.min(dx?n.w/2/Math.abs(dx):1e9,dy?n.h/2/Math.abs(dy):1e9);return [n.x+n.w/2+dx*t,n.y+n.h/2+dy*t];};
 links.forEach(([a,b],k)=>{const A=nodes[a],B=nodes[b],dx=B.x+B.w/2-A.x-A.w/2,dy=B.y+B.h/2-A.y-A.h/2,p=edge(A,dx,dy),q=edge(B,-dx,-dy),g=4/Math.hypot(dx,dy);
  pts['E'+k]=[p[0]+dx*g,p[1]+dy*g];pts['F'+k]=[q[0]-dx*g,q[1]-dy*g];segs.push({v:`E${k}F${k}`,arrows:1,col:1});});
 Object.assign(pts,extra.pts||{});segs.push(...(extra.segs||[]));notes.push(...(extra.notes||[]));
 return fig(title,{pts,polys,segs,notes,view:[0,552,0,h]});};
