const NIGHT=(()=>{const f=3.2,L={W:8.4,REM:6.8,N1:5.2,N2:3.6,N3:2},d3=[.6,.45,.25,.1,0],rem=[.15,.3,.4,.5,.65],iv=[];let t=0;
 const add=(st,d)=>{if(d>1e-9){iv.push([t,t+d,st]);t+=d;}};
 for(let c=0;c<5;c++){const n1=c?0:.1;add('N1',n1);add('N2',.2);add('N3',d3[c]);add('N2',Math.round((1.5-n1-.2-d3[c]-rem[c])*100)/100);add('REM',rem[c]);}
 add('W',.5);
 const pts={},segs=[],notes=[];iv.forEach(([s,e,st],i)=>{pts['P'+i]=[s*f,L[st]];pts['Q'+i]=[e*f,L[st]];segs.push({v:`P${i}Q${i}`,col:st==='REM'?4:0,w:4});if(i)segs.push({v:`Q${i-1}P${i}`,col:3,w:2});});
 Object.assign(notes,[{at:[-3.2,8.4],text:'awake'},{at:[-3.2,6.8],text:'REM'},{at:[-3.2,5.2],text:'N1'},{at:[-3.2,3.6],text:'N2'},{at:[-3.2,2],text:'N3'}]);
 [0,2,4,6,8].forEach(h=>notes.push({at:[h*f,.6],text:h?`${h} h`:'0 h'}));
 pts.B1=[0,9.3];pts.B2=[1.5*f,9.3];segs.push({v:'B1B2',col:2,w:2,label:'one cycle ≈ 90 min',side:1});
 return fig('Fictional night of sleep: schematic stages by hour',{pts,segs,notes,view:[-6.2,27,0,10.4]});})();
